CREATE TABLE public.user_follows (follower_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, followed_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,followed_id), CHECK(follower_id<>followed_id));
GRANT SELECT,INSERT,DELETE ON public.user_follows TO authenticated;
GRANT ALL ON public.user_follows TO service_role;
ALTER TABLE public.user_follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY follows_read ON public.user_follows FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY follows_insert ON public.user_follows FOR INSERT TO authenticated WITH CHECK(follower_id=auth.uid());
CREATE POLICY follows_delete ON public.user_follows FOR DELETE TO authenticated USING(follower_id=auth.uid() OR followed_id=auth.uid());
CREATE INDEX follows_target ON public.user_follows(followed_id);
INSERT INTO public.user_follows(follower_id,followed_id) SELECT sender_id,receiver_id FROM public.friendships WHERE status='accepted' UNION SELECT receiver_id,sender_id FROM public.friendships WHERE status='accepted' ON CONFLICT DO NOTHING;
COMMENT ON TABLE public.friendships IS 'DEPRECATED: accepted connections backfilled as reciprocal user_follows; pending requests are not converted without consent.';
CREATE OR REPLACE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id=a AND followed_id=b) AND EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id=b AND followed_id=a) $$;
CREATE OR REPLACE FUNCTION public.follow_people(uid uuid) RETURNS TABLE(id uuid,display_name text,username text,avatar_url text,following boolean,follower boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name,p.username,p.avatar_url,EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id=uid AND followed_id=p.id),EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id=p.id AND followed_id=uid) FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.id<>uid AND EXISTS(SELECT 1 FROM public.user_follows f WHERE (f.follower_id=uid AND f.followed_id=p.id) OR (f.followed_id=uid AND f.follower_id=p.id)) $$;
REVOKE ALL ON FUNCTION public.follow_people(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.follow_people(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.notify_follow() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.user_notifications(user_id,actor_id,title,target_url) VALUES(NEW.followed_id,NEW.follower_id,'Empezó a seguirte','/people/'||NEW.follower_id::text); RETURN NEW; END $$;
CREATE TRIGGER notify_new_follow AFTER INSERT ON public.user_follows FOR EACH ROW EXECUTE FUNCTION public.notify_follow();
DROP POLICY "Profiles visible to related users" ON public.profiles;
CREATE POLICY "Profiles visible to related users" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR share_visibility='public' OR EXISTS(SELECT 1 FROM public.user_follows f WHERE (f.follower_id=auth.uid() AND f.followed_id=profiles.id) OR (f.followed_id=auth.uid() AND f.follower_id=profiles.id)) OR EXISTS(SELECT 1 FROM public.list_members a JOIN public.list_members b ON a.list_id=b.list_id WHERE a.user_id=auth.uid() AND b.user_id=profiles.id));
DROP POLICY messages_send ON public.direct_messages;
CREATE POLICY messages_send ON public.direct_messages FOR INSERT TO authenticated WITH CHECK(auth.uid()=sender_id AND sender_id<>recipient_id AND EXISTS(SELECT 1 FROM public.user_follows f WHERE (f.follower_id=sender_id AND f.followed_id=recipient_id) OR (f.follower_id=recipient_id AND f.followed_id=sender_id)));